// ----------------------------------------------------------------------
// Tolerances. Skyfield and libsgp4 agree to ~0.005 deg and ~30 m on these
// passes (they differ slightly in Earth rotation and ellipsoid models);
// the limits leave margin for that, not for real errors.
// ----------------------------------------------------------------------

//! Angle between our pointing and Skyfield's, degrees
constexpr double SKY_TOLERANCE_DEG = 0.02;
//! Slant range difference, km
constexpr double RANGE_TOLERANCE_KM = 0.2;
//! AOS/TCA/LOS difference, seconds
constexpr double PASS_TIME_TOLERANCE_S = 1.0;
//! Peak elevation difference, degrees
constexpr double MAX_ELEVATION_TOLERANCE_DEG = 0.02;

//! Angle between two sky directions, degrees. Used instead of comparing
//! azimuths directly, which swing quickly near the zenith.
inline double skySeparationDeg(double az1Deg, double el1Deg, double az2Deg, double el2Deg) {
    const double toRad = 3.14159265358979323846 / 180.0;
    const double cosSep = std::sin(el1Deg * toRad) * std::sin(el2Deg * toRad) +
                          std::cos(el1Deg * toRad) * std::cos(el2Deg * toRad) * std::cos((az1Deg - az2Deg) * toRad);
    return std::acos(std::fmax(-1.0, std::fmin(1.0, cosSep))) / toRad;
}

